// ===== CONFIG =====
// เปลี่ยน TOKEN ได้ที่นี่หรือย้ายไปใส่ใน n8n Variables
const TOKEN = 's6yXmBDu8IHtcIJA54MOVUqxVPNUSwht/oAxwGR+HyZ2H6cbrRS+i2BGQzfQRsCk8rUiVuGiYVSFVqsgW5SJXNIZHi736tS59Q/yJMP7TVfCA0Lot7p1NYu8ERe2tvh3ipTN12+bFfCTQ/8U0ShzYAdB04t89/1O/w1cDnyilFU=';
const LIFF_URL = 'https://liff.line.me/2010228940-rjXFOkmc';

// ===== PARSE BODY =====
const body = $input.first().json.body || $input.first().json;
const events = body.events || [];
if (events.length === 0) return [];

// ===== BUSINESS HOURS CHECK (UTC+7, จ-ส 08:00-17:30) =====
function isBusinessHours() {
  const bkk = new Date(Date.now() + 7 * 3600 * 1000);
  const day = bkk.getUTCDay(); // 0=อาทิตย์
  const t = bkk.getUTCHours() * 60 + bkk.getUTCMinutes();
  return day >= 1 && day <= 6 && t >= 480 && t < 1050;
}

// ===== FLEX: LIFF BUTTON BUBBLE =====
function liffBubble(title, desc, btnLabel) {
  return {
    type: 'flex',
    altText: title,
    contents: {
      type: 'bubble',
      body: {
        type: 'box', layout: 'vertical', spacing: 'md',
        contents: [
          { type: 'text', text: title, weight: 'bold', size: 'lg', wrap: true, color: '#cc0000' },
          { type: 'text', text: desc, size: 'sm', color: '#555555', wrap: true }
        ]
      },
      footer: {
        type: 'box', layout: 'vertical',
        contents: [{
          type: 'button', style: 'primary', color: '#cc0000',
          action: { type: 'uri', label: btnLabel, uri: LIFF_URL }
        }]
      }
    }
  };
}

// ===== PROCESS EACH EVENT =====
const results = [];

for (const event of events) {
  if (!event.replyToken || event.replyToken === '00000000000000000000000000000000') continue;

  let messages = null;

  if (event.type === 'follow') {
    // --- เพิ่มเพื่อน ---
    messages = [
      {
        type: 'text',
        text: 'ยินดีต้อนรับครับ 🏍️\nป.เปา มอเตอร์เซอร์วิส ตัวแทนจำหน่าย Honda วังน้อย\n\nพิมพ์ถามได้เลยครับ หรือกดเมนูด้านล่างเพื่อเลือกรุ่นรถ'
      },
      liffBubble(
        '🛵 ดูรุ่นรถ & คำนวณค่างวด',
        'เลือกรุ่นรถ คำนวณค่างวด ดูราคา ได้ตลอด 24 ชม.',
        'เลือกรุ่นรถเลย'
      )
    ];

  } else if (event.type === 'message' && event.message && event.message.type === 'text') {
    // --- ข้อความ ---
    const raw = (event.message.text || '').trim();
    const tl = raw.toLowerCase();

    if (!isBusinessHours()) {
      // นอกเวลา → ส่ง LIFF link
      messages = [
        liffBubble(
          '❤️ ขอบคุณที่ไว้วางใจ ป.เปา มอเตอร์เซอร์วิส',
          'เราได้รับข้อความของคุณแล้วครับ\n\nหากส่งข้อมูลไว้ ทีมงานจะตรวจสอบและติดต่อกลับในเวลาทำการถัดไป\n\nไม่ต้องรอเจ้าหน้าที่ สามารถเช็กรุ่นรถและคำนวณค่างวดเบื้องต้นได้ตลอด 24 ชั่วโมง',
          'เลือกรุ่นรถ / คำนวณค่างวด'
        )
      ];

    } else if (tl.includes('สาขา') || tl === 'สาขาของเรา') {
      messages = [{
        type: 'text',
        text: '📍 สาขาวังน้อย\n☎️ 092-2499686\n🗺️ https://maps.app.goo.gl/9HexF99DPcKtdtsj9\n\n📍 สาขานครหลวง\n☎️ 092-2499685\n🗺️ https://maps.app.goo.gl/z1qu63BnxFthPtdW9'
      }];

    } else if (tl.includes('เอกสาร') || tl.includes('ออกรถ')) {
      messages = [{
        type: 'image',
        originalContentUrl: 'https://raw.githubusercontent.com/waruton11/porpaor-motorservice/main/images/doc-requirements.png',
        previewImageUrl: 'https://raw.githubusercontent.com/waruton11/porpaor-motorservice/main/images/doc-requirements.png'
      }];

    } else if (tl.includes('myanmar') || tl.includes('myanmar support')) {
      messages = [{
        type: 'text',
        text: 'ဆက်သွယ်ရန် ဖုန်းနံပါတ် ပေးပါ ခင်ဗျာ 📞\nMyanmar staff ဆက်သွယ်ပေးပါမည်ခင်ဗျာ\n\nส่งเบอร์โทรมาได้เลยครับ เซลพม่าจะโทรหาโดยเร็วครับ 😊'
      }];
    }
    // keyword ไม่ตรง + ในเวลาทำการ → ไม่ตอบ ให้พนักงานตอบเอง
  }

  if (messages) {
    results.push({ json: { replyToken: event.replyToken, messages: messages, token: TOKEN } });
  }
}

return results;
